-- 2. ΕΡΕΥΝΗΤΕΣ (25 εγγραφές) - registration_number: NULL
-- ==========================================
('Ανδρέας', 'Καραγιάννης', 'akaragiannis@chaduni.gr', 'https://chaduni.gr/~akaragiannis', 'Μεταδιδακτορικός ερευνητής στη Μηχανική Μάθηση και την ομοσπονδιακή εκμάθηση.\nΣυμμετέχει στην ανάπτυξη μοντέλων με σεβασμό στην ιδιωτικότητα.', 2, NULL),
('Ευαγγελία', 'Τσιώλη', 'etsioli@chaduni.gr', 'https://chaduni.gr/~etsioli', 'Ερευνήτρια σε θέματα Επεξεργασίας Φυσικής Γλώσσας και ανάκτησης πληροφορίας.\nΕξειδικεύεται σε ελληνικά γλωσσικά corpora και αξιολόγηση LLM.', 2, NULL),
('Σπυρίδων', 'Μακρής', 'smakris@chaduni.gr', 'https://chaduni.gr/~smakris', 'Ερευνητής Κατανεμημένων Συστημάτων και Kubernetes/Edge υποδομών.\nΑσχολείται με μετρήσεις απόδοσης και αυτοματοποιημένη κλιμάκωση.', 2, NULL),
('Δέσποινα', 'Βλάχου', 'dvlachou@chaduni.gr', 'https://chaduni.gr/~dvlachou', 'Ερευνήτρια Υπολογιστικής Όρασης με έμφαση στην ιατρική απεικόνιση.\nΑναπτύσσει μοντέλα κατάτμησης και ανίχνευσης παθολογιών.', 2, NULL),
('Χρήστος', 'Καρράς', 'ckarras@chaduni.gr', 'https://chaduni.gr/~ckarras', 'Ερευνητής Κυβερνοασφάλειας σε ανίχνευση εισβολών και ανάλυση κακόβουλου λογισμικού.\nΣυμμετέχει σε ασκήσεις κυβερνοάμυνας και έργα ασφάλειας IoT.', 2, NULL),
('Άννα', 'Λιάκου', 'aliakou@chaduni.gr', 'https://chaduni.gr/~aliakou', 'Ερευνήτρια Βάσεων Δεδομένων και γράφων γνώσης.\nΕρευνά ερωτήματα σε δυναμικούς γράφους και ενοποίηση ετερογενών πηγών.', 2, NULL),
('Πέτρος', 'Σωτηρίου', 'psotiriou@chaduni.gr', 'https://chaduni.gr/~psotiriou', 'Ερευνητής Μηχανικής Λογισμικού σε στατική ανάλυση και ποιότητα κώδικα.\nΑναπτύσσει εργαλεία εντοπισμού τεχνικού χρέους και ευπαθειών.', 2, NULL),
('Ιωάννα', 'Ρούσσου', 'iroussou@chaduni.gr', 'https://chaduni.gr/~iroussou', 'Ερευνήτρια Αλληλεπίδρασης Ανθρώπου-Υπολογιστή και επαυξημένης πραγματικότητας.\nΣχεδιάζει διαδραστικές διεπαφές για εκπαίδευση και πολιτιστική κληρονομιά.', 2, NULL),
('Εμμανουήλ', 'Ζαχαρίου', 'ezachariou@chaduni.gr', 'https://chaduni.gr/~ezachariou', 'Ερευνητής Ρομποτικής και σχεδιασμού τροχιών σε δυναμικά περιβάλλοντα.\nΥλοποιεί αλγόριθμους SLAM και ενισχυτικής μάθησης σε προσομοίωση και πραγματικό υλικό.', 2, NULL),
('Καλλιόπη', 'Θεοδώρου', 'ktheodorou@chaduni.gr', 'https://chaduni.gr/~ktheodorou', 'Ερευνήτρια Επιστήμης Δεδομένων σε χωροχρονικά δεδομένα και βιώσιμη κινητικότητα.\nΑναλύει δεδομένα αισθητήρων και αστικών μετακινήσεων.', 2, NULL),
('Γρηγόριος', 'Παππάς', 'gpappas@chaduni.gr', 'https://chaduni.gr/~gpappas', 'Ερευνητής Αλγορίθμων και βελτιστοποίησης δικτύων.\nΜελετά αλγόριθμους προσέγγισης για προβλήματα δρομολόγησης και κατανομής.', 2, NULL),
('Μαρίνα', 'Κοσμά', 'mkosma@chaduni.gr', 'https://chaduni.gr/~mkosma', 'Ερευνήτρια Τεχνητής Νοημοσύνης με έμφαση στη δεοντολογία και τη διαφάνεια.\nΑξιολογεί μεροληψία αλγορίθμων και αξιοπιστία μοντέλων.', 2, NULL),
('Βασίλειος', 'Δούκας', 'vdoukas@chaduni.gr', 'https://chaduni.gr/~vdoukas', 'Ερευνητής Δικτύων και επικοινωνιών 5G/6G.\nΕρευνά δρομολόγηση σε δίκτυα χαμηλής καθυστέρησης και slicing πόρων.', 2, NULL),
('Φωτεινή', 'Στεργίου', 'fstergiou@chaduni.gr', 'https://chaduni.gr/~fstergiou', 'Ερευνήτρια Πληροφοριακών Συστημάτων και ψηφιακής διακυβέρνησης.\nΑσχολείται με διαλειτουργικότητα υπηρεσιών και σημασιολογικά μοντέλα.', 2, NULL),
('Αθανάσιος', 'Μάρκου', 'amarkou@chaduni.gr', 'https://chaduni.gr/~amarkou', 'Ερευνητής Ενσωματωμένων Συστημάτων και χαμηλής κατανάλωσης.\nΑναπτύσσει εφαρμογές TinyML σε μικροελεγκτές και αισθητήρες.', 2, NULL),
('Ελισάβετ', 'Νταβή', 'ntavi@chaduni.gr', 'https://chaduni.gr/~ntavi', 'Ερευνήτρια Μηχανικής Μάθησης σε πολυτροπικά δεδομένα (εικόνα και κείμενο).\nΕργάζεται σε ευρωπαϊκά ερευνητικά έργα αναγνώρισης σκηνής.', 2, NULL),
('Λάμπρος', 'Χατζής', 'lchatzis@chaduni.gr', 'https://chaduni.gr/~lchatzis', 'Ερευνητής Κατανεμημένων Συστημάτων και επεξεργασίας ροών δεδομένων.\nΑναλύει συστήματα streaming χαμηλού λανθάνοντος χρόνου.', 2, NULL),
('Αγγελική', 'Κυριάκου', 'akyriakou@chaduni.gr', 'https://chaduni.gr/~akyriakou', 'Ερευνήτρια Κυβερνοασφάλειας σε κρυπτογραφικά πρωτόκολλα και blockchain.\nΜελετά επαληθεύσιμους υπολογισμούς και ασφάλεια έξυπνων συμβολαίων.', 2, NULL),
('Στέφανος', 'Πολίτης', 'spolitis@chaduni.gr', 'https://chaduni.gr/~spolitis', 'Ερευνητής Βάσεων Δεδομένων σε αναλυτικά συστήματα στήλης και lakehouses.\nΕρευνά συμπίεση δεδομένων και ταχεία εκτέλεση αναλυτικών ερωτημάτων.', 2, NULL),
('Νεφέλη', 'Βαρδάκη', 'nvardaki@chaduni.gr', 'https://chaduni.gr/~nvardaki', 'Ερευνήτρια NLP σε συναισθηματική ανάλυση και αναγνώριση οντοτήτων.\nΣυμμετέχει σε δημοσιεύσεις και ανοιχτά ερευνητικά εργαλεία.', 2, NULL),
('Ηλίας', 'Φωτίου', 'ifotiou@chaduni.gr', 'https://chaduni.gr/~ifotiou', 'Ερευνητής Υπολογιστικής Όρασης σε παρακολούθηση αντικειμένων και αυτόνομη οδήγηση.\nΑσχολείται με ανθεκτικότητα μοντέλων σε δυσμενείς καιρικές συνθήκες.', 2, NULL),
('Ολυμπία', 'Γαλάνη', 'ogalani@chaduni.gr', 'https://chaduni.gr/~ogalani', 'Ερευνήτρια Επιστήμης Δεδομένων σε βιοπληροφορική και γονιδιωματική.\nΕφαρμόζει στατιστικά μοντέλα και μηχανική μάθηση σε βιολογικά δεδομένα.', 2, NULL),
('Τριαντάφυλλος', 'Λεοντίου', 'tleontiou@chaduni.gr', 'https://chaduni.gr/~tleontiou', 'Ερευνητής Μηχανικής Λογισμικού σε αυτοματοποιημένη επισκευή σφαλμάτων.\nΜελετά τεχνικές παραγωγής patch και ανάλυσης ιστορικού αποθετηρίων.', 2, NULL),
('Κυριακή', 'Μάνου', 'kmanou@chaduni.gr', 'https://chaduni.gr/~kmanou', 'Ερευνήτρια HCI σε ψηφιακή προσβασιμότητα και υποστηρικτικές τεχνολογίες.\nΑξιολογεί διεπαφές για άτομα με προβλήματα όρασης και κινητικότητας.', 2, NULL),
('Ισίδωρος', 'Δαμιανού', 'idamianou@chaduni.gr', 'https://chaduni.gr/~idamianou', 'Ερευνητής Ρομποτικής και συνεργατικών ρομπότ (cobots).\nΕστιάζει στην ασφαλή φυσική αλληλεπίδραση ανθρώπου-ρομπότ.', 2, NULL),

